import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:share_plus/share_plus.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import '../../../core/theme/app_theme.dart';

class AdminScreen extends ConsumerWidget{const AdminScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final admin=ref.watch(isAdminProvider).asData?.value??false;return Scaffold(appBar:AppBar(title:const Text('Administration')),body:ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:AppColors.teal,borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ACCOUNT',style:TextStyle(color:Colors.white70,letterSpacing:1)),const SizedBox(height:6),Text(ref.watch(authRepositoryProvider).currentUser?.email??'Signed in',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800,fontSize:17)),Text(admin?'Administrator privileges':'Standard account',style:const TextStyle(color:Colors.white70))]),),const SectionTitle('Business settings'),_tile(context,'Invoice terms','Edit printed terms and conditions',Icons.description_outlined,()=>_editTerms(context,ref)),_tile(context,'Backup & restore','Export or restore Firestore business records',Icons.backup_outlined,()=>_backup(context,ref)),_tile(context,'Refresh cloud data','Reload all synchronized collections',Icons.sync,()=>ref.invalidate(billsProvider)),const SectionTitle('Account'),_tile(context,'Sign out','Sign out of Firebase Authentication',Icons.logout,()async{await ref.read(authRepositoryProvider).signOut();}),if(!admin)const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Admin-only actions require a Firebase Authentication custom claim: admin = true.')))]));}}
Widget _tile(BuildContext c,String title,String sub,IconData icon,VoidCallback onTap)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(onTap:onTap,leading:CircleAvatar(backgroundColor:AppColors.paleBlue.withValues(alpha:.3),child:Icon(icon,color:AppColors.teal)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(sub),trailing:const Icon(Icons.chevron_right)));
Future<void> _editTerms(BuildContext context,WidgetRef ref)async{final repo=ref.read(billingRepositoryProvider);final current=await repo.get('settings','terms_invoice');final ctrl=TextEditingController(text:'${current?['value']??'1) Rent is cycle-based (15/20/30 days as per bill).\n2) Transport/Loading/Unloading applies only in first cycle.\n3) Advance is security deposit.'}');if(!context.mounted)return;final save=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Invoice terms'),content:SizedBox(width:480,child:TextField(controller:ctrl,maxLines:9,decoration:const InputDecoration(labelText:'Terms and conditions'))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(save==true)await repo.put('settings',{'key':'terms_invoice','value':ctrl.text});ctrl.dispose();}
Future<void> _backup(BuildContext context,WidgetRef ref)async{final repo=ref.read(billingRepositoryProvider);final names=['bills','customers','customBills','slips','challans','inventory','settings'];final data=<String,List<Map<String,dynamic>>>{};for(final n in names){data[n]=await repo.all(n);}if(!context.mounted)return;await showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Wrap(runSpacing:12,children:[Text('Backup & restore',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text('${data.values.fold<int>(0,(s,x)=>s+x.length)} records across ${names.length} Firestore collections.'),FilledButton.icon(onPressed:()async{final json=const JsonEncoder.withIndent('  ').convert({'schema':'sa-traders-firestore-v1','exported_at':DateTime.now().toUtc().toIso8601String(),'business':businessName,'data':data});await SharePlus.instance.share(ShareParams(text:json,subject:'S.A Traders JSON backup'));},icon:const Icon(Icons.ios_share),label:const Text('Share JSON backup')),OutlinedButton.icon(onPressed:()=>_restore(context,ref),icon:const Icon(Icons.upload_file_outlined),label:const Text('Restore from pasted JSON')),if(ref.read(isAdminProvider).asData?.value==true)TextButton.icon(onPressed:()=>_reset(context,ref),icon:const Icon(Icons.delete_forever_outlined,color:AppColors.red),label:const Text('Reset business records',style:TextStyle(color:AppColors.red)))]))));}
Future<void> _restore(BuildContext context,WidgetRef ref)async{final ctrl=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Restore JSON backup'),content:SizedBox(width:500,child:TextField(controller:ctrl,maxLines:10,decoration:const InputDecoration(hintText:'Paste the full S.A Traders JSON backup'))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Validate & restore'))]));if(ok!=true)return;try{final obj=jsonDecode(ctrl.text) as Map<String,dynamic>;final source=obj['data'] as Map<String,dynamic>;final stores=<String,List<Map<String,dynamic>>>{};for(final name in storeKeys.keys){if(source[name]!=null){final rows=(source[name] as List).map((x)=>Map<String,dynamic>.from(x as Map)).toList();final key=storeKeys[name]!;if(rows.any((r)=>'${r[key]??''}'.trim().isEmpty))throw FormatException('Some $name records have no $key.');stores[name]=rows;}}if(stores.isEmpty)throw const FormatException('No recognized data collections.');if(!context.mounted)return;final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Replace matching data?'),content:Text('This replaces ${stores.values.fold<int>(0,(v,x)=>v+x.length)} records in ${stores.keys.join(', ')}.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Replace'))]));if(yes==true){await ref.read(billingRepositoryProvider).replaceAll(stores);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Backup restored')));}}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Restore failed: $e')));}finally{ctrl.dispose();}}
Future<void> _reset(BuildContext context,WidgetRef ref)async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Reset business records?'),content:const Text('This permanently clears bills, customers, custom bills, slips and challans.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Reset'))]));if(yes==true){for(final s in ['bills','customers','customBills','slips','challans']){for(final row in await ref.read(billingRepositoryProvider).all(s)){await ref.read(billingRepositoryProvider).delete(s,'${row[storeKeys[s]]}');}}}}
